// dashboard-panel.tsx
"use client";
import { useState } from "react";
import { RevenueChart } from "./revenue-chart"; // 120KB charting lib inside
import { ServerSummary } from "./server-summary"; // async server component (awaits db)

export function DashboardPanel({
  rows,
  formatCell,
}: {
  rows: { id: string; total: number }[];
  formatCell: (n: number) => string;
}) {
  const [expanded, setExpanded] = useState(false);
  return (
    <section>
      <button onClick={() => setExpanded(!expanded)}>Toggle details</button>
      <RevenueChart rows={rows} />
      {expanded && <ServerSummary />}
      <ul>
        {rows.map((r) => (
          <li key={r.id}>{formatCell(r.total)}</li>
        ))}
      </ul>
    </section>
  );
}
